{
  "steps": [
    {
      "id": 1,
      "claim": "Einstein’s photoelectric equation gives the maximum kinetic energy of emitted electrons as K_max = h·ν – φ.",
      "evidence": "Einstein’s 1905 theory of the photoelectric effect, confirmed experimentally.",
      "weight": 0.30,
      "depends_on": []
    },
    {
      "id": 2,
      "claim": "The stopping potential V_s satisfies e·V_s = K_max.",
      "evidence": "Definition of stopping (retarding) potential: the electric work eV_s exactly cancels the maximum kinetic energy of the photoelectrons.",
      "weight": 0.20,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "Substituting K_max from step 1 into step 2 gives V_s = (h/e)·ν – φ/e.",
      "evidence": "Algebraic substitution and solving for V_s.",
      "weight": 0.15,
      "depends_on": [1, 2]
    },
    {
      "id": 4,
      "claim": "Introducing the threshold frequency ν₀ = φ/h rewrites the expression as V_s = (h/e)(ν – ν₀).",
      "evidence": "Definition of threshold frequency where photon energy equals the work function.",
      "weight": 0.15,
      "depends_on": [3]
    },
    {
      "id": 5,
      "claim": "For frequencies ν > ν₀, V_s is a linear function of ν with slope h/e.",
      "evidence": "Equation in step 4 is of the form y = m·x + c, valid only when ν exceeds the threshold so that electrons are emitted.",
      "weight": 0.10,
      "depends_on": [4]
    },
    {
      "id": 6,
      "claim": "Option (D) states exactly this linear relationship between the stopping potential and the frequency above the threshold.",
      "evidence": "Option D wording matches the conclusion of step 5.",
      "weight": 0.05,
      "depends_on": [5]
    }
  ],
  "answer": "D",
  "confidence": 0.98,
  "considered": [
    {
      "answer": "A",
      "reason_rejected": "The work function φ is an intrinsic material constant; it does not vary with the incident light frequency."
    },
    {
      "answer": "B",
      "reason_rejected": "The work function is independent of wavelength; photon energy varies as 1/λ, not proportionally."
    },
    {
      "answer": "C",
      "reason_rejected": "Photocurrent depends on light intensity (number of photons), not linearly on wavelength."
    }
  ]
}
